<script setup lang="ts">
import { computed } from 'vue'
import {nodeConditionState} from '@/utils/kubernetesNode'
import {formatDateTime} from '@/utils/time'
import { useI18n } from 'vue-i18n'
import { podSpec, type KubeObject, type KubeType } from '@/api/kubernetes'
import { resourceCells, resourceColumns, ingressRoutes, podReferences, policyDirections, policyPeer, type KubeReference } from '@/utils/kubernetesPresentation'
import KubeResourceCell from './KubeResourceCell.vue'
const props=defineProps<{object:KubeObject;type:KubeType;canFollow:(reference?:KubeReference)=>boolean}>()
const emit=defineEmits<{follow:[reference:KubeReference]}>()
const {t}=useI18n()
const cells=computed(()=>resourceCells(props.object,t))
const fields=computed(()=>resourceColumns(props.type,t).filter(item=>!['name','namespace','status','created','usage','images'].includes(item.key)))
const containers=computed(()=>[...(podSpec(props.object).initContainers??[]).map((item:KubeObject)=>({...item,init:true})),...(podSpec(props.object).containers??[])])
const references=computed(()=>podReferences(props.object))
const routes=computed(()=>ingressRoutes(props.object))
const policyRules=computed(()=>policyDirections(props.object).flatMap(direction=>(props.object.spec?.[direction.toLowerCase()]??[]).map((rule:KubeObject,index:number)=>({direction,index,peers:rule[direction==='Ingress'?'from':'to']??[],ports:rule.ports??[]}))))
const parameters=computed(()=>Object.entries(props.object.parameters??{}))
const source=computed(()=>{const spec=props.object.spec??{};if(spec.csi)return {label:'CSI',value:`${spec.csi.driver} / ${spec.csi.volumeHandle}`};if(spec.nfs)return {label:'NFS',value:`${spec.nfs.server}:${spec.nfs.path}`};if(spec.local)return {label:'Local',value:spec.local.path};if(spec.hostPath)return {label:'HostPath',value:spec.hostPath.path};return undefined})
const containerState=(container:KubeObject)=>{
  const state=[...(props.object.status?.containerStatuses??[]),...(props.object.status?.initContainerStatuses??[])].find((item:KubeObject)=>item.name===container.name)
  return state?.state?.waiting?.reason??state?.state?.terminated?.reason??(state?.state?.running?t('k8s.state_running'):'—')
}
const resources=(container:KubeObject,field:string)=>['cpu','memory','ephemeral-storage'].filter(key=>container.resources?.[field]?.[key]!==undefined).map(key=>`${key}: ${container.resources[field][key]}`).join(' · ')||'—'
</script>
<template>
  <section v-if="fields.length" class="resource-detail-section kube-facts-section"><h4>{{ t('k8s.resourceSettings') }}</h4><dl class="kube-detail-facts"><div v-for="field in fields" :key="field.key"><dt>{{ field.label }}</dt><dd><KubeResourceCell :cell="cells[field.key]" :date="['jobTiming','lastSchedule'].includes(field.key)" :can-follow="canFollow(cells[field.key]?.reference)" @follow="emit('follow',$event)" /></dd></div></dl></section>

  <section v-if="containers.length" class="resource-detail-section"><h4>{{ t('k8s.containers') }}</h4><div class="detail-table-scroll"><table class="kube-detail-table"><thead><tr><th>{{ t('k8s.container') }}</th><th>{{ t('k8s.image') }}</th><th>{{ t('k8s.ports') }}</th><th>{{ t('k8s.resourceRequests') }}</th><th>{{ t('k8s.resourceLimits') }}</th><th v-if="object.kind==='Pod'">{{ t('k8s.status') }}</th></tr></thead><tbody><tr v-for="container in containers" :key="container.name"><td><strong>{{ container.name }}</strong><span v-if="container.init" class="muted">Init</span></td><td><code>{{ container.image }}</code></td><td>{{ (container.ports??[]).map((item:KubeObject)=>`${item.containerPort}/${item.protocol??'TCP'}`).join(' · ')||'—' }}</td><td>{{ resources(container,'requests') }}</td><td>{{ resources(container,'limits') }}</td><td v-if="object.kind==='Pod'">{{ containerState(container) }}</td></tr></tbody></table></div></section>

  <section v-if="references.length" class="resource-detail-section"><h4>{{ t('k8s.referencedResources') }}</h4><div class="reference-list"><div v-for="reference in references" :key="`${reference.resource}/${reference.name}`"><span class="muted">{{ t(`k8s.type_${reference.resource}`) }}</span><button v-if="canFollow(reference)" class="detail-link" @click="emit('follow',reference)">{{ reference.name }}</button><span v-else>{{ reference.name }}</span></div></div></section>

  <section v-if="object.kind==='Service'" class="resource-detail-section"><h4>{{ t('k8s.portMapping') }}</h4><div class="detail-table-scroll"><table class="kube-detail-table"><thead><tr><th>{{ t('k8s.name') }}</th><th>{{ t('k8s.protocol') }}</th><th>{{ t('k8s.servicePort') }}</th><th>{{ t('k8s.targetPort') }}</th><th>NodePort</th></tr></thead><tbody><tr v-for="port in object.spec?.ports??[]" :key="`${port.port}/${port.protocol}`"><td>{{ port.name||'—' }}</td><td>{{ port.protocol??'TCP' }}</td><td>{{ port.port }}</td><td>{{ port.targetPort??port.port }}</td><td>{{ port.nodePort??'—' }}</td></tr></tbody></table></div><dl class="kube-detail-facts additional-facts"><div><dt>{{ t('k8s.sessionAffinity') }}</dt><dd>{{ object.spec?.sessionAffinity??'None' }}</dd></div><div><dt>{{ t('k8s.externalTrafficPolicy') }}</dt><dd>{{ object.spec?.externalTrafficPolicy??'—' }}</dd></div><div><dt>{{ t('k8s.publishNotReady') }}</dt><dd>{{ t(object.spec?.publishNotReadyAddresses?'k8s.yes':'k8s.no') }}</dd></div></dl><p class="detail-hint">{{ t('k8s.serviceReachabilityHint') }}</p></section>

  <section v-if="object.kind==='Ingress'" class="resource-detail-section"><h4>{{ t('k8s.routes') }}</h4><div class="detail-table-scroll"><table class="kube-detail-table"><thead><tr><th>{{ t('k8s.hostname') }}</th><th>{{ t('k8s.path') }}</th><th>{{ t('k8s.pathType') }}</th><th>{{ t('k8s.backend') }}</th><th>{{ t('k8s.servicePort') }}</th></tr></thead><tbody><tr v-for="(route,index) in routes" :key="index"><td>{{ route.host }}</td><td>{{ route.path }}</td><td>{{ route.pathType }}</td><td><button v-if="route.service&&canFollow({resource:'services',name:route.service,namespace:object.metadata.namespace})" class="detail-link" @click="emit('follow',{resource:'services',name:route.service!,namespace:object.metadata.namespace})">{{ route.service }}</button><span v-else>{{ route.service??route.resource??'—' }}</span></td><td>{{ route.port??'—' }}</td></tr></tbody></table></div><a-empty v-if="!routes.length" :description="t('k8s.emptyData')" /><div v-if="object.spec?.tls?.length" class="tls-list"><div v-for="(tls,index) in object.spec.tls" :key="index"><span>{{ (tls.hosts??[]).join(', ')||'*' }}</span><span class="muted">Secret</span><button v-if="tls.secretName&&canFollow({resource:'secrets',name:tls.secretName,namespace:object.metadata.namespace})" class="detail-link" @click="emit('follow',{resource:'secrets',name:tls.secretName,namespace:object.metadata.namespace})">{{ tls.secretName }}</button><span v-else>{{ tls.secretName||'—' }}</span></div></div><p class="detail-hint">{{ t('k8s.ingressReachabilityHint') }}</p></section>

  <section v-if="object.kind==='NetworkPolicy'" class="resource-detail-section"><h4>{{ t('k8s.policyRules') }}</h4><p class="detail-hint">{{ t('k8s.policyRulesHint') }}</p><a-empty v-if="!policyRules.length" :description="t('k8s.denySelectedDirections')" /><div v-else class="detail-table-scroll"><table class="kube-detail-table"><thead><tr><th>{{ t('k8s.policyDirection') }}</th><th>{{ t('k8s.sourceOrDestination') }}</th><th>{{ t('k8s.allowedPorts') }}</th></tr></thead><tbody><tr v-for="rule in policyRules" :key="`${rule.direction}/${rule.index}`"><td>{{ t(rule.direction==='Ingress'?'k8s.ingressTraffic':'k8s.egressTraffic') }} #{{ rule.index+1 }}</td><td><div v-for="(peer,index) in rule.peers" :key="index">{{ policyPeer(peer,t) }}</div><span v-if="!rule.peers.length">{{ t('k8s.allTraffic') }}</span></td><td>{{ rule.ports.length?rule.ports.map((port:KubeObject)=>`${port.port??'*'}${port.endPort?`–${port.endPort}`:''}/${port.protocol??'TCP'}`).join(' · '):t('k8s.allPorts') }}</td></tr></tbody></table></div></section>

  <section v-if="object.kind==='PersistentVolume'||object.kind==='StorageClass'" class="resource-detail-section"><h4>{{ t('k8s.storageSettings') }}</h4><dl class="kube-detail-facts"><div v-if="source"><dt>{{ source.label }}</dt><dd>{{ source.value }}</dd></div><div><dt>{{ t('k8s.mountOptions') }}</dt><dd>{{ (object.mountOptions??object.spec?.mountOptions??[]).join(', ')||'—' }}</dd></div><div v-for="[key,value] in parameters" :key="key"><dt>{{ key }}</dt><dd>{{ value }}</dd></div></dl></section>

  <section v-if="object.status?.conditions?.length" class="resource-detail-section"><h4>{{ t('k8s.conditions') }}</h4><div class="detail-table-scroll"><table class="kube-detail-table"><thead><tr><th>{{ t('k8s.conditionType') }}</th><th>{{ t('k8s.status') }}</th><th>{{ t('k8s.reason') }}</th><th>{{ t('k8s.message') }}</th><th>{{ t('k8s.nodeHeartbeat') }}</th><th>{{ t('k8s.nodeTransition') }}</th></tr></thead><tbody><tr v-for="condition in object.status.conditions" :key="condition.type"><td>{{ condition.type }}</td><td><a-tag :color="object.kind==='Node'?nodeConditionState(condition):'default'">{{ condition.status }}</a-tag></td><td>{{ condition.reason||'—' }}</td><td>{{ condition.message||'—' }}</td><td>{{ formatDateTime(condition.lastHeartbeatTime) }}</td><td>{{ formatDateTime(condition.lastTransitionTime) }}</td></tr></tbody></table></div></section>
</template>
<style scoped>
h4{font-size:13px;margin:0 0 12px}.kube-detail-facts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0 24px;margin:0}.kube-detail-facts>div{padding:11px 0;border-bottom:1px solid var(--edo-border);min-width:0}dt{color:var(--edo-muted);font-size:12px;margin-bottom:7px}dd{font-size:13px;margin:0;overflow-wrap:anywhere}.additional-facts{margin-top:10px}.detail-table-scroll{overflow-x:auto}.kube-detail-table{width:100%;border-collapse:collapse;font-size:13px;text-align:left}.kube-detail-table th{background:var(--edo-bg);color:var(--edo-muted);font-size:12px;font-weight:500;white-space:nowrap}.kube-detail-table th,.kube-detail-table td{padding:10px 12px;border-bottom:1px solid var(--edo-border);vertical-align:top;min-width:90px;line-height:1.6}.kube-detail-table code{display:block;min-width:200px;max-width:330px;overflow-wrap:anywhere;font-size:12px}.muted{color:var(--edo-muted);font-size:12px;margin-left:5px}.detail-hint{font-size:12px;color:var(--edo-muted);margin:12px 0 0;line-height:1.7}.detail-link{border:0;background:none;padding:0;color:var(--edo-primary);cursor:pointer;text-align:left;font:inherit;overflow-wrap:anywhere}.detail-link:hover{text-decoration:underline}.reference-list{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.reference-list>div{display:grid;gap:6px;font-size:13px;min-width:0}.reference-list .muted{margin:0}.tls-list{margin-top:12px;display:grid;gap:8px;font-size:13px}.tls-list>div{display:flex;align-items:center;gap:12px;flex-wrap:wrap}@media(max-width:800px){.kube-detail-facts,.reference-list{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:480px){.kube-detail-facts,.reference-list{grid-template-columns:1fr}}
</style>
